def balancedParenthesesAndSum(expression):
    stack = []
    digit_sum = 0

    for char in expression:
        if char == '(':
            stack.append(char)
        elif char.isdigit():
            digit_sum += int(char)
        elif char == ')' and stack:
            stack.pop()

    if len(stack) != 0:
        return -1
    else:
        return digit_sum

# Test cases
print(balancedParenthesesAndSum("(1(2)3)"))  # Output: 6
print(balancedParenthesesAndSum("((1)23)"))  # Output: 6
print(balancedParenthesesAndSum(")(1(2)3"))  # Output: -1

