def balancedParenthesesAndSum(expression):
    stack = []
    digit_sum = 0

    for char in expression:
        if char == '(':
            stack.append(char)
        elif char.isdigit():
            digit_sum += int(char)
        elif char == ')' and stack:
            stack.pop()

    if len(stack) != 0:
        return -1
    else:
        return digit_sum

