def kthSmallest(mat, k):
    m, n = len(mat), len(mat[0])

    def countLessThan(target):
        count = 0
        i, j = m - 1, 0

        while i >= 0 and j < n:
            if mat[i][j] <= target:
                count += i + 1
                j += 1
            else:
                i -= 1

        return count

    left, right = mat[0][0], mat[m-1][n-1]

    while left < right:
        mid = (left + right) // 2
        if countLessThan(mid) < k:
            left = mid + 1
        else:
            right = mid

    return left

